sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var birthDate = new Date(g_form.getValue('date_of_birth'));
    var today = new Date();

    var age = today.getFullYear() - birthDate.getFullYear();
    var monthDiff = today.getMonth() - birthDate.getMonth();

    // Adjusting of age if the birth month/day hasn't occurred yet in this year.
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
        age--;
    }

    if (age < 18 && g_form.getValue('temporary_profile') == 'false') {
		g_form.setDisplay('guardian', true);
		g_form.setMandatory('guardian', true);
        return;
    }
	else if (age < 18 && g_form.getValue('temporary_profile') == 'true') {
		g_form.setDisplay('guardian', true);
        return;
	}
	else if(age >= 18) {
		g_form.setMandatory('guardian', false);
		g_form.setDisplay('guardian', false);
    }

}
